-- Bibliothèque d'aliments — données CIQUAL 2025 (ANSES, Licence Ouverte / Etalab).

-- GÉNÉRÉ par supabase/scripts/enrich-ciqual/generate.py — NE PAS éditer à la main (régénérer).

-- Migration volontairement IDEMPOTENTE (upsert) : réconcilie les aliments existants sur le cloud

-- et se rejoue sans effet de bord au db:reset. Attribution : Table Ciqual, ANSES.



on conflict (id) do update set
  source = excluded.source, category = excluded.category, barcode = excluded.barcode,
  kcal_per_100g = excluded.kcal_per_100g, protein_per_100g = excluded.protein_per_100g,
  carbs_per_100g = excluded.carbs_per_100g, sugars_per_100g = excluded.sugars_per_100g,
  fat_per_100g = excluded.fat_per_100g, saturated_fat_per_100g = excluded.saturated_fat_per_100g,
  fiber_per_100g = excluded.fiber_per_100g, portions = excluded.portions,
  micronutrients = excluded.micronutrients, updated_at = now();

on conflict (id) do update set name = excluded.name, updated_at = now();
